-- Коды других вариантов УЛ, значение которых отличается от ФБИР.484430.013, и код E36 преобразователя Hpmont.
-- Тексты пересказаны своими словами по руководствам производителя, это справочник.

INSERT INTO causes (title, source) VALUES
    ('Заклинил при выключении один из пускателей привода дверей', 'ФАИД.484430.013 РЭ, прил. Д'),
    ('Постоянно замкнут ключ переменного тока платы ПСК, управляющий пускателями привода дверей', 'ФАИД.484430.013 РЭ, прил. Д'),
    ('Неисправна (разомкнута) цепь обратной связи пускателей привода дверей', 'ФАИД.484430.013 РЭ, прил. Д')
AS new
ON DUPLICATE KEY UPDATE source = new.source;

INSERT INTO fault_codes (controller_id, code, title, description, is_safety_related, source)
SELECT c.id, v.code, v.title, v.description, v.safety, c.doc_ref
FROM controllers c
JOIN (
    SELECT 'УЛ ФАИД.484430.013 (ГОСТ Р 53780, автоматические двери)' AS controller, '57' AS code,
           'Нет сигнала о выключении пускателей привода дверей' AS title,
           'По окончании открытия или закрытия дверей цепь обратной связи пускателей привода дверей осталась разомкнутой. УЛ останавливает лифт и выключает реле К1 «АВАРИЯ», на индикаторе периодически появляется 57. Лифт возвращается в работу после устранения неисправности. В руководстве у названия кода стоит пометка «не используется». В основном варианте УЛ ФБИР.484430.013 тот же номер 57 означает другое: нет сигнала о выключении стопорного устройства.' AS description,
           1 AS safety
    UNION ALL SELECT 'УЛ ФБИР.484440.500 (ГОСТ 33984.1, ручные двери)', '45', 'Нет импульсов от устройства контроля скорости',
           'Только для нерегулируемого привода. Контроль идёт во всех режимах. Если после включения пускателей направления и скорости УЛ не фиксирует импульсы на выходе УКС1, формируется код 45 и лифт аварийно останавливается. Восстановить работу можно только после выключения тумблера SA1 «СЕТЬ» и устранения неисправности. В варианте УЛ ФБИР.484430.013 тот же номер 45 означает другое: нет готовности преобразователя частоты.', 0
    UNION ALL SELECT 'УЛ ФБИР.484440.500 (ГОСТ 33984.1, ручные двери)', '46', 'Разомкнута цепь дверей при неподвижной кабине вне зоны точной остановки',
           'Для неподвижной кабины вне зоны точной остановки разомкнута блокировочная цепь дверей кабины или (и) цепь замков дверей шахты. Система возвращается в рабочее состояние после устранения неисправности.', 1
    UNION ALL SELECT 'УЛ ФБИР.484440.500 (ГОСТ 33984.1, ручные двери)', 'd0', 'Дверь открыли и закрыли без открытия парной двери',
           'В режиме НОРМАЛЬНАЯ РАБОТА открыли и затем закрыли дверь шахты (кабины), не открывая дверь кабины (шахты). Лифт возвращается в работу после открытия двери шахты и двери кабины. Код также формируется, если в режиме НОРМАЛЬНАЯ РАБОТА после выключения отводки и замкнутой цепи контроля дверей кабины цепь дверных замков осталась замкнутой.', 1
    UNION ALL SELECT 'УЛ ФБИР.484440.500 (ГОСТ 33984.1, ручные двери)', 'd1', 'Три остановки подряд без открытия дверей',
           'В процессе работы выполнено три остановки без открытия дверей шахты и кабины. Система возвращается в работу после открытия двери шахты и кабины.', 0
    UNION ALL SELECT 'УЛ ФАИД.484440.002 (ГОСТ Р 56943, ручные двери)', '45', 'Нет импульсов от устройства контроля скорости',
           'Только для нерегулируемого привода. Контроль идёт во всех режимах. Если после включения пускателей направления и скорости УЛ не фиксирует импульсы на выходе УКС1, формируется код 45 и лифт аварийно останавливается. Восстановить работу можно только после выключения тумблера SA1 «СЕТЬ» и устранения неисправности. В варианте УЛ ФБИР.484430.013 тот же номер 45 означает другое: нет готовности преобразователя частоты.', 0
    UNION ALL SELECT 'УЛ ФАИД.484440.002 (ГОСТ Р 56943, ручные двери)', '46', 'Разомкнута цепь дверей при неподвижной кабине вне зоны точной остановки',
           'Для неподвижной кабины вне зоны точной остановки разомкнута блокировочная цепь дверей кабины или (и) цепь замков дверей шахты. Система возвращается в рабочее состояние после устранения неисправности.', 1
    UNION ALL SELECT 'УЛ ФАИД.484440.002 (ГОСТ Р 56943, ручные двери)', 'd0', 'Дверь открыли и закрыли без открытия парной двери',
           'В режиме НОРМАЛЬНАЯ РАБОТА открыли и затем закрыли дверь шахты (кабины), не открывая дверь кабины (шахты). Лифт возвращается в работу после открытия двери шахты и двери кабины. Код также формируется, если в режиме НОРМАЛЬНАЯ РАБОТА после выключения отводки и замкнутой цепи контроля дверей кабины цепь дверных замков осталась замкнутой.', 1
    UNION ALL SELECT 'УЛ ФАИД.484440.002 (ГОСТ Р 56943, ручные двери)', 'd1', 'Три остановки подряд без открытия дверей',
           'В процессе работы выполнено три остановки без открытия дверей шахты и кабины. Система возвращается в работу после открытия двери шахты и кабины.', 0
    UNION ALL SELECT 'ПЧ Hpmont HD5L', 'E36', 'Ошибка обратной связи пускателя (контактора) или тормоза',
           'Код преобразователя частоты Hpmont HD5L. Таблица ошибок ПЧ называет две причины: повреждён пускатель (контактор) и ошибка подключения контакта обратной связи, действия по таблице: заменить пускатель и проверить подключение. В методике проверки контроля колодок тормоза руководства лифта 0401К при отключённом проводе КТА или КТВ в режиме МП2 через 2 секунды E36 появляется в ПЧ вместе с кодом 45 в УЛ, кабина останавливается.', 1
) v ON v.controller = c.name
ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), is_safety_related = VALUES(is_safety_related), source = VALUES(source);

INSERT IGNORE INTO fault_code_causes (fault_code_id, cause_id)
SELECT fc.id, ca.id
FROM (
    SELECT 'УЛ ФАИД.484430.013 (ГОСТ Р 53780, автоматические двери)' AS controller, '57' AS code, 'Заклинил при выключении один из пускателей привода дверей' AS c_title
    UNION ALL SELECT 'УЛ ФАИД.484430.013 (ГОСТ Р 53780, автоматические двери)', '57', 'Постоянно замкнут ключ переменного тока платы ПСК, управляющий пускателями привода дверей'
    UNION ALL SELECT 'УЛ ФАИД.484430.013 (ГОСТ Р 53780, автоматические двери)', '57', 'Неисправна (разомкнута) цепь обратной связи пускателей привода дверей'
    UNION ALL SELECT 'УЛ ФАИД.484430.013 (ГОСТ Р 53780, автоматические двери)', '57', 'Неисправна плата ПУ устройства УЛ'
    UNION ALL SELECT 'ПЧ Hpmont HD5L', 'E36', 'Повреждён пускатель или контактор'
    UNION ALL SELECT 'ПЧ Hpmont HD5L', 'E36', 'Неверно подключён контакт обратной связи пускателя или тормоза'
) l
JOIN controllers c ON c.name = l.controller
JOIN fault_codes fc ON fc.controller_id = c.id AND fc.code = l.code
JOIN causes ca ON ca.title = l.c_title;

INSERT IGNORE INTO fault_code_symptoms (fault_code_id, symptom_id)
SELECT fc.id, s.id
FROM fault_codes fc
JOIN controllers c ON c.id = fc.controller_id
JOIN symptoms s ON s.title = 'Остановка с ошибкой E36 в ПЧ Hpmont (в УЛ код 45): ошибка обратной связи пускателя или тормоза'
WHERE (c.name = 'УЛ ФБИР.484430.013 (ГОСТ 33984.1, автоматические двери)' AND fc.code = '45')
   OR (c.name = 'ПЧ Hpmont HD5L' AND fc.code = 'E36');
